def pp125_standing_png(data, standings_rows):
    """Export a clean mobile-style leaderboard PNG that looks close to the on-screen standings."""
    W = 1080
    margin = 32
    row_h = 126
    top = 170
    footer = 112
    H = top + len(standings_rows) * row_h + footer
    canvas = Image.new('RGBA', (W, H), '#F6FAF9')
    dr = ImageDraw.Draw(canvas)
    fontdir = '/usr/share/fonts/truetype/dejavu/'

    def font(size, bold=False):
        try:
            return ImageFont.truetype(fontdir + ('DejaVuSans-Bold.ttf' if bold else 'DejaVuSans.ttf'), size)
        except OSError:
            return ImageFont.load_default()

    def fit(text, max_width, start_size=40, min_size=22, bold=True):
        txt = str(text)
        size = start_size
        while size > min_size and dr.textbbox((0, 0), txt, font=font(size, bold))[2] > max_width:
            size -= 1
        if dr.textbbox((0, 0), txt, font=font(size, bold))[2] > max_width:
            while len(txt) > 1 and dr.textbbox((0, 0), txt + '…', font=font(size, bold))[2] > max_width:
                txt = txt[:-1]
            txt += '…'
        return txt, font(size, bold)

    def center(x, y, text, f, fill):
        bbox = dr.textbbox((0, 0), str(text), font=f)
        dr.text((x - (bbox[2] - bbox[0]) / 2, y), str(text), font=f, fill=fill)

    # Clean compact header, not a big poster block
    title = data.get('title') or 'Turnering'
    subtitle = 'SLUTSTILLING' if finals_complete(data) else 'STILLING'
    dr.text((margin, 24), subtitle, font=font(30, True), fill='#138777')
    title_txt, title_font = fit(title, 700, 58, 34, True)
    dr.text((margin, 58), title_txt, font=title_font, fill='#1B3136')
    meta = f"{data.get('format', 'Padel')} · {len(standings_rows)} spillere"
    dr.text((margin, 118), meta, font=font(24), fill='#657B7D')

    # Small transparent logo top-right
    try:
        img = Image.open(BytesIO(zlib.decompress(base64.b64decode(_PP125_LOGO)))).convert('RGBA')
        img.thumbnail((175, 120), Image.Resampling.LANCZOS)
        canvas.alpha_composite(img, (W - margin - img.width, 28 + (110 - img.height)//2))
    except Exception:
        pass

    cols = [margin + 16, margin + 82, 665, 740, 815, 900, 1000]
    for x, txt in zip(cols, ['#', 'Spiller', 'V', 'U', 'T', '+/-', 'Point']):
        if x >= 660:
            center(x, top - 36, txt, font(22, True), '#536B6F')
        else:
            dr.text((x, top - 36), txt, font=font(22, True), fill='#536B6F')

    for idx, row in enumerate(standings_rows):
        y = top + idx * row_h
        bg = ('#FFF7DF', '#F0F3F7', '#FFF0E7')[idx] if idx < 3 else '#FFFFFF'
        outline = ('#D6AA3A', '#AAB9C8', '#C68A64')[idx] if idx < 3 else '#DDEAE8'
        dr.rounded_rectangle((margin, y + 4, W - margin, y + row_h - 8), radius=28, fill=bg, outline=outline, width=4 if idx < 3 else 2)

        if idx < 3:
            medal_color = ('#D5A224', '#A8B4C2', '#B7774A')[idx]
            dr.ellipse((margin + 14, y + 34, margin + 72, y + 92), fill=medal_color)
            center(margin + 43, y + 45, str(idx + 1), font(28, True), '#FFFFFF')
        else:
            dr.text((cols[0], y + 42), str(idx + 1) + '.', font=font(32, True), fill='#23393C')

        name, name_f = fit(row['name'], 430, 33, 22, True)
        dr.text((cols[1], y + 40), name, font=name_f, fill='#20383B')
        diff = int(row['diff'])
        values = [row['wins'], row['draws'], row['losses'], f'{diff:+d}', row['points']]
        for x, v in zip(cols[2:], values):
            center(x, y + 42, str(v), font(31, x == cols[-1]), '#18363A')

    end = top + len(standings_rows) * row_h
    dr.text((margin + 2, end + 18), 'V = Vundne · U = Uafgjorte · T = Tabte · +/- = Pointforskel', font=font(22), fill='#64787B')
    out = BytesIO()
    canvas.convert('RGB').save(out, format='PNG', optimize=True)
    return out.getvalue()


with tab_table:
    st.subheader('🏆 Leaderboard')
    if finals_complete(d):
        st.caption('Slutstilling inkl. finalen · flest samlede point først, derefter sejre, pointforskel og navn')
    else:
        st.caption(f"Sortering: {d.get('ranking_priority', 'Point først')} · derefter {'scorede point' if d.get('ranking_priority') == 'Sejre først' else 'sejre'}, pointforskel og navn")
    rows=standings(d)
    if not rows:
        st.info('Tilføj spillere for at se stillingen.')
    else:
        st.markdown('<div class="standing-heading"><span>#</span><span class="standing-person">Spiller</span><span>V</span><span>U</span><span>T</span><span>+/-</span><span>Point</span></div>',unsafe_allow_html=True)
        for i,r in enumerate(rows):
            diff=f'+{r["diff"]}' if r['diff']>0 else str(r['diff'])
            name=html.escape(r['name'])
            award = ('gold', 'silver', 'bronze')[i] if i < 3 else ''
            rank = ('🥇', '🥈', '🥉')[i] if i < 3 else f'{i+1}.'
            st.markdown(
                f'<div class="standing-row {award}">'
                f'<span class="standing-rank">{rank}</span><span class="standing-person">{name}</span>' 
                f'<span class="standing-value">{r["wins"]}</span>'
                f'<span class="standing-value">{r["draws"]}</span>'
                f'<span class="standing-value">{r["losses"]}</span>'
                f'<span class="standing-value standing-diff">{diff}</span>'
                f'<span class="standing-value standing-points">{r["points"]}</span>'
                '</div>',unsafe_allow_html=True)
        st.caption('V = Vundne · U = Uafgjorte · T = Tabte · +/- = Pointforskel')
        # Delingsbilledet tegnes i browseren efter den samme mobil-leaderboardstruktur.
        # Billedfilen klargøres INDEN brugeren trykker: Web Share API kræver brugeraktivering.
        try:
            share_rows = [dict(rank=i+1, name=r['name'], wins=r['wins'],
                               draws=r['draws'], losses=r['losses'],
                               diff=r['diff'], points=r['points'])
                          for i, r in enumerate(rows)]
            share_payload = json.dumps(share_rows, ensure_ascii=False)
            share_title = json.dumps(str(d.get('title') or 'Padel Pappas'), ensure_ascii=False)
            share_subtitle = json.dumps(f"{d.get('format','Padel')} · {len(rows)} spillere", ensure_ascii=False)
            share_logo = base64.b64encode(zlib.decompress(base64.b64decode(_PP125_LOGO))).decode('ascii')
            share_html = r"""<!doctype html><html lang="da"><head><meta name="viewport" content="width=device-width,initial-scale=1" />
            <style>
            html,body{margin:0;padding:0;background:transparent;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
            button{display:block;width:100%;min-height:52px;border:0;border-radius:15px;background:#148479;color:white;font-size:17px;font-weight:650;cursor:pointer}
            button:disabled{opacity:.55}
            #msg{font-size:13px;color:#526e70;min-height:18px;margin:5px 3px}
            </style></head><body>
            <button id="share" type="button" disabled>↗ Klargør stilling …</button><div id="msg" role="status"></div>
            <script>
            const rows=__ROWS__,title=__TITLE__,subtitle=__SUBTITLE__;
            const logo='data:image/png;base64,__LOGO__';
            const btn=document.getElementById('share'),msg=document.getElementById('msg');
            let readyFile=null;
            const W=1080, H=190+rows.length*119+64;
            const canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;
            const ctx=canvas.getContext('2d');
            function roundRect(x,y,w,h,r,fill,stroke,lineWidth=2){
              ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();
              if(stroke){ctx.lineWidth=lineWidth;ctx.strokeStyle=stroke;ctx.stroke();}
            }
            function text(t,x,y,size=30,bold=false,color='#26363d',align='left'){
              ctx.font=`${bold?'700':'400'} ${size}px -apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif`;
              ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(String(t),x,y);
            }
            function ellipse(x,y,r,color){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
            function draw(logoImg){
              ctx.fillStyle='#F7FAF9';ctx.fillRect(0,0,W,H);
              text(title,40,53,43,true,'#233B3E');text(subtitle,40,105,26,false,'#688084');
              if(logoImg)ctx.drawImage(logoImg,878,12,160,135);
              const xs=[58,145,670,743,816,914,1010];
              ['#','Spiller','V','U','T','+/-','Point'].forEach((v,i)=>text(v,xs[i],171,26,true,'#26383D',i>1?'center':'left'));
              rows.forEach((r,i)=>{
                const y=192+i*119;
                const bg=i===0?'#FFF7E3':i===1?'#F1F4F8':i===2?'#FFF1E8':'#FFFFFF';
                const border=i===0?'#D6AA3A':i===1?'#ABB8C7':i===2?'#C68A64':'#DDE9EB';
                roundRect(40,y,1000,102,30,bg,border,i<3?4:2);
                if(i<3){ellipse(88,y+51,29,['#D8AA25','#ADB8C2','#B9794D'][i]);text(i+1,88,y+51,30,true,'#FFF','center');}
                else text(`${i+1}.`,61,y+51,32,true);
                let nameSize=33;let name=String(r.name);
                while(nameSize>21){ctx.font=`700 ${nameSize}px Arial`;if(ctx.measureText(name).width<455)break;nameSize--;}
                text(name,145,y+51,nameSize,true);
                [r.wins,r.draws,r.losses,r.diff>0?`+${r.diff}`:r.diff,r.points].forEach((v,j)=>text(v,xs[j+2],y+51,31,j===4,'#293C40','center'));
              });
              text('V = Vundne · U = Uafgjorte · T = Tabte · +/- = Pointforskel',43,H-29,22,false,'#697D81');
            }
            function prepare(){
              canvas.toBlob(blob=>{
                if(!blob){msg.textContent='Kunne ikke klargøre billedet.';return;}
                readyFile=new File([blob],'Padel-Pappas-8362-Stilling.png',{type:'image/png'});
                btn.disabled=false;btn.textContent='↗ Del stilling';
              },'image/png');
            }
            const im=new Image();
            im.onload=()=>{draw(im);prepare();};
            im.onerror=()=>{draw(null);prepare();};
            im.src=logo;
            btn.addEventListener('click',async()=>{
              if(!readyFile)return;
              // No await before navigator.share: preserve iOS user gesture.
              if(!navigator.share || !navigator.canShare || !navigator.canShare({files:[readyFile]})){
                msg.textContent='Fildeling er blokeret i dette Streamlit-appvindue. Åbn appen direkte i Safari for at prøve igen.';return;
              }
              try{await navigator.share({files:[readyFile],title:'Padel Pappas 8362 – '+title});}
              catch(e){if(e?.name!=='AbortError')msg.textContent='iPhone kunne ikke dele billedet fra appvinduet.';}
            });
            </script></body></html>"""
            share_html = (share_html.replace('__ROWS__', share_payload)
                             .replace('__TITLE__', share_title)
                             .replace('__SUBTITLE__', share_subtitle)
                             .replace('__LOGO__', share_logo))
            components.html(share_html, height=93, scrolling=False)
        except Exception as share_exc:
            st.warning(f'Kunne ikke klargøre deling af stillingen: {share_exc}')

        with st.expander('Se komplette statistikker'):
            st.dataframe([{'Spiller':r['name'],'KS':r['played'],'V':r['wins'],'U':r['draws'],'T':r['losses'],'Point':r['points'],'PF':r['diff']} for r in rows],hide_index=True,use_container_width=True)


def pp97_history_court(match, round_number):
    """En låst HTML-bane, med samme layout som den interaktive kampbane."""
    def esc(value):
        return html.escape(str(value), quote=True)
    saved = match.get('blue_score') is not None and match.get('red_score') is not None
    blue_score = esc(match['blue_score']) if saved else '–'
    red_score = esc(match['red_score']) if saved else '–'
    badge = '✓ Gemt' if saved else 'Afventer'
    status_class = '' if saved else ' pending'
    names = []
    for team in ('blue','red'):
        for name in match[team]:
            names.append(f'<span class="pp97-name">{esc(name)}</span>')
        # Supports shorter teams without breaking the court alignment.
        while len(names) < (2 if team == 'blue' else 4):
            names.append('<span class="pp97-name"></span>')
    foot = 'Resultatet er gemt' if saved else 'Kampen er endnu ikke gemt som afgjort'
    return (
        '<div class="pp97-card"><div class="pp97-top">'
        f'<span class="pp97-pill">Bane {esc(match["court"])}</span>'
        f'<span class="pp97-badge{status_class}">{badge}</span>'
        '</div><div class="pp97-court">'
        '<div class="pp97-service left"></div><div class="pp97-service right"></div>'
        '<div class="pp97-midline left"></div><div class="pp97-midline right"></div>'
        '<div class="pp97-net"></div>'
        f'<div class="pp97-team blue">{names[0]}{names[1]}</div>'
        f'<div class="pp97-team red">{names[2]}{names[3]}</div>'
        '<div class="pp97-vs">VS</div>'
        f'<div class="pp97-score blue{status_class}">{blue_score}</div>'
        f'<div class="pp97-score red{status_class}">{red_score}</div>'
        '</div>'
        f'<div class="pp97-foot">{foot}</div></div>'
    )

with tab_log:
    st.subheader('📜 Kamphistorik')
    rounds = d['history'] + ([{'number':d['round'],'matches':d['matches']}] if d['matches'] else [])
    if not rounds:
        st.info('Ingen runder spillet endnu.')
    else:
        round_numbers = sorted({r['number'] for r in rounds})
        st.caption('Vælg runde')
        history_view_key = f'pp101_history_round_{st.session_state.get("tid", "")}'
        if st.session_state.get(history_view_key) not in round_numbers:
            st.session_state[history_view_key] = round_numbers[-1]
        for start in range(0, len(round_numbers), 4):
            columns = st.columns(min(4, len(round_numbers) - start), gap='small')
            for column, number in zip(columns, round_numbers[start:start + 4]):
                with column:
                    if st.button(f'Runde {number}', key=f'pp101_h_{start}_{number}',
                                 type='primary' if st.session_state[history_view_key] == number else 'secondary',
                                 use_container_width=True):
                        st.session_state[history_view_key] = number
        selected_round = st.session_state[history_view_key]
        selected = next(r for r in rounds if r['number'] == selected_round)
        st.caption('Vælg en runde for at se resultater. Tryk på Ret resultat for at ændre.')
        for j, m in enumerate(selected['matches']):
            st.markdown(pp97_history_court(m, selected_round), unsafe_allow_html=True)
            with st.container(key=f'pp116_history_edit_{selected_round}_{j}'):
                with st.popover('✎ Ret resultat', use_container_width=False):
                    st.write(f'**Runde {selected_round} · Bane {m["court"]}**')
                    st.caption('Ændringer gemmes først, når du trykker Gem rettelse.')
                    with st.form(f"pp97_fix_{selected_round}_{j}"):
                        c1,c2=st.columns(2)
                        newb=c1.number_input('Blåt hold',min_value=0,
                                             max_value=int(d['target']) if d['target'] else 200,
                                             value=int(m['blue_score'] or 0),key=f'pp97_b_{selected_round}_{j}')
                        if d['target']:
                            newr=int(d['target'])-newb
                            c2.metric('Rødt hold',newr)
                        else:
                            newr=c2.number_input('Rødt hold',min_value=0,max_value=200,
                                                 value=int(m['red_score'] or 0),key=f'pp97_r_{selected_round}_{j}')
                        if st.form_submit_button('Gem rettelse', type='primary'):
                            if d['target'] and newb+newr != d['target']:
                                st.error(f'Scorerne skal tilsammen være {d["target"]} point.')
                            else:
                                m['blue_score']=int(newb)
                                m['red_score']=int(newr)
                                save()
                                st.success('Resultatet er gemt.')
                                st.rerun()
